from youtube_dl.downloader.dash import DashSegmentsFD
fd = DashSegmentsFD.__new__(DashSegmentsFD)
fd.params = {'fragment_retries': 0, 'skip_unavailable_fragments': True, 'test': False}
appended = []
state = {}
def _prepare(ctx):
    ctx['fragment_index'] = 0
    state['prepared'] = dict(ctx)
def _download(ctx, fragment_url, info_dict):
    return (True, fragment_url.encode('utf-8'))
def _append(ctx, frag_content):
    appended.append(frag_content)
def _finish(ctx):
    state['finished'] = True
fd._prepare_and_start_frag_download = _prepare
fd._download_fragment = _download
fd._append_fragment = _append
fd._finish_frag_download = _finish
result = fd.real_download('out.mp4', {'fragment_base_url': 'http://example.com/', 'fragments': [{'url': 'http://example.com/seg1.m4s'}, {'url': 'http://example.com/seg2.m4s'}]})
assert result is True
